import random
random.seed(7)
msgs = [("005930", p) for p in (71000, 71100, 71200, 71300)] + [("000660", p) for p in (180000, 180500)]

# ① 아무 일꾼 스레드나 집어 가는 풀: 끝나는 순서가 처리 시간에 달려 있다
done = sorted(msgs, key=lambda m: msgs.index(m) + random.uniform(0, 3))
last = {}
for code, p in done:
    last[code] = p
print("스레드 풀  ->", last)

# ② 종목코드로 이벤트 루프를 고른다(hash % N): 한 종목은 늘 같은 한 줄로 선다
N = 4
loops = [[] for _ in range(N)]
for code, p in msgs:
    loops[int(code) % N].append((code, p))
last = {}
for q in loops:
    for code, p in q:
        last[code] = p
print("종목별 루프 ->", last)
print("루프별 줄 길이:", [len(q) for q in loops])
